<script setup lang="ts">import{ref}from'vue';import PageHeader from'../../components/PageHeader.vue';import{client,errorMessage,requireData}from'../../../shared/api/client';import type{components}from'../../../shared/api/schema.gen';const id=ref('');const value=ref<components['schemas']['DebugTrace']>();const error=ref('');async function load(){try{value.value=requireData(await client.GET('/api/admin/qa/debug/{id}',{params:{path:{id:id.value}}}))}catch(cause){error.value=errorMessage(cause)}}</script>
<template><PageHeader title="问答调试台"/><form class="flex gap-2" @submit.prevent="load"><input v-model="id" class="nw-input" placeholder="调试记录 ID"><button class="nw-button">读取</button></form><p v-if="error" class="text-danger">{{ error }}</p><article v-for="step in value?.steps" :key="step.name" class="mt-4 rounded-card border border-border p-4"><strong>{{ step.name }}</strong><pre class="overflow-auto">{{ step.output }}</pre><small>{{ step.duration }} ns · ${{ step.cost }}</small></article></template>
